const tabId = 480038377;
const results = await browserjs(tabId, () => {
  // Google image search results are usually in elements with data-docid or jsaction or inside specific containers
  const items = [];
  const links = Array.from(document.querySelectorAll('a[href*="imgurl"], div[data-docid], a[jsname]'));

  // Let's find image links
  const anchors = Array.from(document.querySelectorAll('a')).filter(a => {
    return a.href && (a.href.includes('/imgres') || a.querySelector('img') || a.getAttribute('data-nav'));
  });

  return anchors.slice(0, 20).map(a => ({
    href: a.href,
    text: a.textContent?.trim().slice(0, 100),
    ariaLabel: a.getAttribute('aria-label'),
    title: a.getAttribute('title'),
    imgSrc: a.querySelector('img')?.src?.slice(0, 80)
  }));
});
console.log("Results sample:", JSON.stringify(results.slice(0, 10), null, 2));

const tabId = 480038377;
const imageCards = await browserjs(tabId, () => {
  // Let's look for search results
  // In modern Google Images, results are typically inside div[data-id] or div[jsaction*="click"] or a with role="button" or similar
  const cards = [];
  // Find elements with images and titles
  const allImages = Array.from(document.querySelectorAll('div[data-docid], div[data-id], div[jsname][data-ri]'));

  // Let's also check all <a> tags that have href containing imgres or external sites
  const imgresLinks = Array.from(document.querySelectorAll('a[href*="/imgres"]'));

  // Also check divs inside the search results container
  const resultDivs = Array.from(document.querySelectorAll('h3, div[role="listitem"]'));

  return {
    allImagesCount: allImages.length,
    imgresCount: imgresLinks.length,
    sampleImgres: imgresLinks.slice(0, 10).map(a => ({
      href: a.href,
      text: a.textContent?.trim().slice(0, 80),
      imgAlt: a.querySelector('img')?.alt
    })),
    resultDivsSample: resultDivs.slice(0, 10).map(d => ({
      tag: d.tagName,
      text: d.textContent?.trim().slice(0, 100),
      html: d.innerHTML.slice(0, 100)
    }))
  };
});
console.log("Image cards info:", JSON.stringify(imageCards, null, 2));

