const tabId = 480038377;
const results = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('div[data-docid]'));
  const unique = [];
  const seen = new Set();
  for (const c of cards) {
    const lpage = c.getAttribute('data-lpage');
    const docid = c.getAttribute('data-docid');
    const img = c.querySelector('img');
    const alt = img?.alt || c.textContent?.trim();
    if (lpage && !seen.has(lpage)) {
      seen.add(lpage);
      unique.push({ docid, lpage, alt: alt.slice(0, 150) });
    }
  }
  return unique;
});
console.log("Unique image results:", JSON.stringify(results.slice(0, 10), null, 2));

