const tabId = 480038377;
try {
  await tool.element_interact({ tabId, ref: "e63628", operation: "click" });
} catch (e) {
  console.log("Cookie consent dismiss:", e.message);
}

const text = await browserjs(tabId, () => {
  return document.body.innerText;
});

// Search for PowerPoint or slides
const lines = text.split('\n');
const pptLines = [];
for (let i = 0; i < lines.length; i++) {
  if (lines[i].toLowerCase().includes('powerpoint') || lines[i].toLowerCase().includes('slides')) {
    pptLines.push(lines.slice(Math.max(0, i-2), Math.min(lines.length, i+15)).join('\n'));
  }
}

console.log("PPT sections found count:", pptLines.length);
console.log(pptLines.join('\n---\n'));

